import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"错误处理与重试","description":"","frontmatter":{"title":"错误处理与重试"},"headers":[],"relativePath":"api/general/error-handling.md","filePath":"api/general/error-handling.md","lastUpdated":1795698978000}'),o={name:"api/general/error-handling.md"};function l(i,t,c,n,h,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<p>本节介绍调用 API 时如何处理错误，以及哪些情况适合自动重试。</p><h2 id="是否可以重试" tabindex="-1">是否可以重试 <a class="header-anchor" href="#是否可以重试" aria-label="Permalink to &quot;是否可以重试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>是否重试</th><th>说明</th></tr></thead><tbody><tr><td><code>429</code></td><td>可以</td><td>等待后重试，采用指数退避</td></tr><tr><td><code>502</code></td><td>视请求类型而定</td><td>服务暂时不可用，见下文</td></tr><tr><td>网络超时、连接中断</td><td>视请求类型而定</td><td>见下文</td></tr><tr><td><code>400</code></td><td>不应重试</td><td>修正请求参数后再发起</td></tr><tr><td><code>401</code></td><td>不应重试</td><td>检查 API Key</td></tr><tr><td><code>404</code></td><td>不应重试</td><td>检查资源 ID 与账户</td></tr><tr><td><code>409</code></td><td>不应立即重试</td><td>先查询资源状态，满足条件后再操作</td></tr></tbody></table><h2 id="查询类请求" tabindex="-1">查询类请求 <a class="header-anchor" href="#查询类请求" aria-label="Permalink to &quot;查询类请求&quot;">​</a></h2><p><code>GET</code> 请求不会改变资源状态，遇到 <code>429</code>、<code>502</code> 或网络错误时可以直接重试。</p><h2 id="操作类请求" tabindex="-1">操作类请求 <a class="header-anchor" href="#操作类请求" aria-label="Permalink to &quot;操作类请求&quot;">​</a></h2><p><code>POST</code> 操作类请求会改变资源状态。如果请求发出后出现超时、连接中断或返回 <code>502</code>，您无法确定指令是否已经下发，此时请<strong>不要直接重试</strong>：</p><ol><li>调用详情接口，查询资源当前状态。</li><li>如果状态已经变化或正在变化，说明指令已经下发，无需重试。</li><li>如果状态未发生变化，再重新发起操作。</li></ol><h2 id="设置超时时间" tabindex="-1">设置超时时间 <a class="header-anchor" href="#设置超时时间" aria-label="Permalink to &quot;设置超时时间&quot;">​</a></h2><p>建议为每个请求设置客户端超时时间，例如 30 秒，避免程序长时间等待。</p><h2 id="推荐的重试策略" tabindex="-1">推荐的重试策略 <a class="header-anchor" href="#推荐的重试策略" aria-label="Permalink to &quot;推荐的重试策略&quot;">​</a></h2><ul><li>采用指数退避：第 1 次等待 1 秒，第 2 次等待 2 秒，第 3 次等待 4 秒，依此类推。</li><li>设置最大等待时间，例如 30 秒，以及最大重试次数，例如 5 次。</li><li>超过最大重试次数后停止重试，记录错误信息和 <code>X-Request-Id</code>。</li></ul><h2 id="记录请求信息" tabindex="-1">记录请求信息 <a class="header-anchor" href="#记录请求信息" aria-label="Permalink to &quot;记录请求信息&quot;">​</a></h2><p>为便于排查问题，建议在日志中记录以下信息：</p><ul><li>请求方法与路径</li><li>HTTP 状态码</li><li>响应头中的 <code>X-Request-Id</code></li><li>响应体中的 <code>error_message</code></li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>请勿在日志中记录 API Key。</p></div>',16)])])}const _=e(o,[["render",l]]);export{u as __pageData,_ as default};
